exec(open("explore/t2/w.py").read())
con.sql("create view s as select * from 'work/window/side_links_q1_ddr.parquet' where rule='T2.dd_return'")
con.sql("create table sg as select s.*, g.item_id is not null ok, regexp_extract(evidence,'code=([^;]*)',1) code, regexp_extract(evidence,'n_cand=([^;]*)',1)::int n_cand from s left join g on g.bank_txn_id=s.bank_txn_id and g.item_id=s.item_id")
q("select code='MD06' md06, n_cand>1 amb, evidence like '%skipped%' moved, ok, count(*) from sg group by all order by all")
q("select confidence>=0.8 hi, ok, count(*) from sg group by all order by all")
q("select bank_txn_id, item_id, confidence, evidence from sg where not ok and n_cand=1")
con.sql("create table e1 as select sg.bank_txn_id, sg.item_id sub_item, g.item_id g_item, regexp_extract(evidence,'batch_id=([^;]*)',1) b, regexp_extract(evidence,'mandate=([^;]*)',1) m from sg join g using(bank_txn_id) where not ok and n_cand=1")
q("select e1.bank_txn_id, d.remittance_info, d.amount, d.end_to_end_id, d.debtor_name from e1 join dd d on d.batch_id=e1.b and d.mandate_id=e1.m")
q("select e1.bank_txn_id, i.item_id = e1.g_item gold, i.doc_number, i.party_id, i.entity, i.issue_date, i.total_cents, i.open_at_start_cents from e1 join it i on i.item_id in (e1.sub_item, e1.g_item) order by 1, 2")
